mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.z += time * 1.2;
  vec3 c = abs(mod(p, 2.0) - 1.0);
  float box = max(c.x, max(c.y, c.z)) - 0.7;
  float cross3 = min(max(c.x, c.y), min(max(c.y, c.z), max(c.z, c.x))) - 0.35;
  return max(box, -cross3);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.5));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 15.0) break;
    t += d * 0.75;
  }
  vec3 col = vec3(0.01, 0.04, 0.02);
  if (t < 15.0) {
    vec3 pos = ro + rd * t;
    float fog = 1.0 / (1.0 + t * t * 0.03);
    float edge = step(0.68, max(abs(mod(pos.x, 2.0)-1.0), abs(mod(pos.y, 2.0)-1.0)));
    col = (vec3(0.0, 0.25, 0.12) + edge * vec3(0.3, 1.0, 0.5) * 1.5) * fog;
  }
  ret = col;
}
